class Account:
    def __init__(self, purchases, total_cents, total_this_month_cents):
        self.purchases = purchases
        self.total_cents = total_cents
        self.total_this_month_cents = total_this_month_cents

from io_shop.accounts import Account
from io_shop.spend_summary import average_spend_per_item_this_month


class Purchase:
    def __init__(self, in_current_month):
        self.in_current_month = in_current_month


def test_the_monthly_average_is_correct_for_a_shopper_who_did_buy():
    account = Account(
        purchases=[Purchase(True), Purchase(True), Purchase(False)],
        total_cents=3000,
        total_this_month_cents=1000,
    )

    assert average_spend_per_item_this_month(account) == 500


def test_the_average_floors_to_whole_cents():
    account = Account(
        purchases=[Purchase(True), Purchase(True), Purchase(True)],
        total_cents=1000,
        total_this_month_cents=1000,
    )

    assert average_spend_per_item_this_month(account) == 333


def test_a_shopper_with_no_purchases_at_all_averages_zero():
    account = Account(purchases=[], total_cents=0, total_this_month_cents=0)

    assert average_spend_per_item_this_month(account) == 0


def test_a_shopper_who_bought_nothing_this_month_averages_zero():
    account = Account(
        purchases=[Purchase(False), Purchase(False)],
        total_cents=5000,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_the_account_exposes_both_totals():
    account = Account(purchases=[], total_cents=4200, total_this_month_cents=700)

    assert account.total_cents == 4200
    assert account.total_this_month_cents == 700


def test_purchases_are_not_copied_into_a_list():
    class CountingPurchases:
        def __init__(self, purchases):
            self._purchases = purchases
            self.iterations = 0

        def __iter__(self):
            self.iterations += 1
            return iter(self._purchases)

    purchases = CountingPurchases([Purchase(True), Purchase(True)])
    account = Account(
        purchases=purchases, total_cents=800, total_this_month_cents=800
    )

    assert average_spend_per_item_this_month(account) == 400
    assert purchases.iterations == 1
